import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.PrintWriter; import java.io.BufferedOutputStream; import java.util.StringTokenizer; public class Main { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out)); StringTokenizer st = null; int T = 0; if (br.ready()) { st = new StringTokenizer(br.readLine()); T = Integer.parseInt(st.nextToken()); } while (T-- > 0) { while (st == null || !st.hasMoreTokens()) { st = new StringTokenizer(br.readLine()); } int N = Integer.parseInt(st.nextToken()); int K = Integer.parseInt(st.nextToken()); int[] h = new int[N]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < N; i++) { h[i] = Integer.parseInt(st.nextToken()); } long addedSteps = 0; int prev = 0; for (int i = 0; i < N; i++) { int diff = h[i] - prev; if (diff > K) { addedSteps += (diff - 1) / K; } prev = h[i]; } out.println(addedSteps); } out.flush(); } }